# Validation
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not isinstance(arr, np.ndarray):
        raise ValueError("Input must be a numpy array")
    if arr.ndim != 2:
        raise ValueError("Input must be 2-dimensional")
    if arr.size == 0:
        raise ValueError("Input must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError("Input contains non-finite values")
    if np.any(arr > 0):
        raise ValueError("Input contains positive values")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Input shapes must match")
if isinstance(tau_filter, bool):
    raise ValueError("Threshold must not be boolean")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("Threshold must be finite nonnegative")
loss_wr = -np.sum(logp_with_result, axis=1)
loss_co = -np.sum(logp_call_only, axis=1)
loss_nc = -np.sum(logp_no_call, axis=1)
better_no_call = loss_wr < loss_nc
better_call_only = loss_wr < loss_co
improvement = np.minimum(loss_nc, loss_co) - loss_wr
keep = better_no_call & better_call_only & (improvement > tau_filter)
return keep, improvement
